import {parsePages,renderSize} from './logic.mjs';
const $=id=>document.getElementById(id);
let engine,zipLibrary,pdf,task,busy=false,cancelled=false,items=[],base='document';
const status=(message,error=false)=>{$('status').textContent=message;$('status').classList.toggle('error',error)};
function lock(value){busy=value;for(const id of ['options','drop','replace','demo','file']) $(id).disabled=value;$('convert').disabled=value||!pdf;$('cancel').hidden=!value;$('zip').disabled=value||!items.length;}
function clearResults(){for(const item of items) URL.revokeObjectURL(item.url);items=[];$('results').replaceChildren();$('resultsSection').hidden=true;$('zip').disabled=true;}
async function load(file){if(busy||!engine)return;if(!file||!file.name.toLowerCase().endsWith('.pdf'))return status('Please choose a PDF file.',true);if(file.size>100*1024*1024)return status('Please choose a PDF smaller than 100 MB.',true);lock(true);clearResults();status('Opening your document…');try{if(pdf)await pdf.destroy();pdf=null;$('document').hidden=true;$('drop').hidden=false;task=engine.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:'./vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'./vendor/standard_fonts/',wasmUrl:'./vendor/wasm/'});task.onPassword=(update,reason)=>{const password=window.prompt(reason===1?'This PDF is protected. Enter its password:':'Incorrect password. Please try again:');if(password===null){task.destroy();return;}update(password);};pdf=await task.promise;base=file.name.replace(/\.pdf$/i,'').replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_')||'document';$('filename').textContent=file.name;$('filemeta').textContent=`${pdf.numPages} page${pdf.numPages===1?'':'s'} · ${(file.size/1048576).toFixed(2)} MB`;$('drop').hidden=true;$('document').hidden=false;$('pages').value='';status('Document ready. Choose your settings and convert.');}catch(error){status('Could not open this PDF. It may be damaged, or the password entry was cancelled.',true);pdf=null;}finally{lock(false);$('file').value='';}}
$('drop').onclick=$('replace').onclick=()=>$('file').click();$('file').onchange=event=>load(event.target.files[0]);
for(const name of ['dragover','dragleave','drop'])$('drop').addEventListener(name,event=>{event.preventDefault();$('drop').classList.toggle('drag',name==='dragover');if(name==='drop')load(event.dataTransfer.files[0]);});
$('format').onchange=()=>{const visible=$('format').value==='jpeg';$('quality').hidden=$('qualityLabel').hidden=!visible;};$('quality').oninput=()=>{$('qualityValue').textContent=$('quality').value+'%';};
$('cancel').onclick=()=>{cancelled=true;$('cancel').disabled=true;status('Stopping after the current page…');};
function blobFrom(canvas,type,quality){return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Image export failed. Try a lower DPI.')),type,quality));}
$('convert').onclick=async()=>{let pages;try{pages=parsePages($('pages').value,pdf.numPages);}catch(error){return status(error.message,true);}clearResults();lock(true);cancelled=false;$('cancel').disabled=false;$('progress').hidden=false;$('progress').value=0;const dpi=Number($('dpi').value),format=$('format').value,quality=Number($('quality').value)/100;let totalBytes=0;try{for(const number of pages){if(cancelled)break;status(`Rendering page ${number} · ${items.length+1} of ${pages.length}…`);const page=await pdf.getPage(number);const size=renderSize(page.getViewport({scale:1}),dpi);const canvas=document.createElement('canvas');canvas.width=size.width;canvas.height=size.height;try{await page.render({canvasContext:canvas.getContext('2d'),viewport:page.getViewport({scale:dpi/72}),background:'#ffffff'}).promise;const blob=await blobFrom(canvas,`image/${format}`,quality);totalBytes+=blob.size;if(totalBytes>400*1024*1024)throw new Error('This batch exceeds 400 MB. Download these pages, then convert a smaller page range.');const url=URL.createObjectURL(blob);const filename=`${base}-page-${String(number).padStart(3,'0')}-${dpi}dpi.${format==='jpeg'?'jpg':'png'}`;items.push({blob,url,filename});const card=document.createElement('article');card.className='result';const img=new Image();img.src=url;img.alt=`Preview of page ${number}`;img.loading='lazy';const title=document.createElement('strong');title.textContent=`Page ${number}`;const detail=document.createElement('p');detail.textContent=`${size.width} × ${size.height} px · ${(blob.size/1048576).toFixed(2)} MB`;const link=document.createElement('a');link.href=url;link.download=filename;link.textContent=`Download ${format==='jpeg'?'JPG':'PNG'} ↓`;card.append(img,title,detail,link);$('results').append(card);$('resultsSection').hidden=false;$('count').textContent=`(${items.length})`;$('progress').value=items.length/pages.length*100;}finally{canvas.width=canvas.height=0;page.cleanup();}await new Promise(resolve=>setTimeout(resolve,0));}status(cancelled?`Stopped. ${items.length} completed images are ready to download.`:`Done! ${items.length} images ready — download individually or as a ZIP.`);}catch(error){status(error.message||'Conversion failed. Try a lower DPI or fewer pages.',true);}finally{lock(false);$('progress').hidden=true;}};
$('zip').onclick=async()=>{if(!items.length)return;lock(true);$('cancel').hidden=true;status('Preparing your ZIP download…');try{const files={};for(const item of items)files[item.filename]=new Uint8Array(await item.blob.arrayBuffer());const bytes=await new Promise((resolve,reject)=>zipLibrary.zip(files,{level:0},(error,data)=>error?reject(error):resolve(data)));const url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'}));const a=document.createElement('a');a.href=url;a.download=`${base}-images.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status('ZIP download started. Your individual images are still available.');}catch(error){status('Could not create ZIP. Download individual images or use a smaller batch.',true);}finally{lock(false);}};
$('demo').onclick=async()=>{try{const response=await fetch('./sample.pdf');if(!response.ok)throw new Error();await load(new File([await response.blob()],'sample.pdf',{type:'application/pdf'}));}catch{status('Could not load the sample. Please choose your own PDF.',true);}};
try{[engine,zipLibrary]=await Promise.all([import('./vendor/pdf.mjs'),import('./vendor/fflate.mjs')]);engine.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.mjs';status('Ready when you are. Choose a PDF to get started.');}catch(error){status('The conversion engine could not load. Refresh in an up-to-date Chrome, Edge, Firefox or Safari browser.',true);$('drop').disabled=$('demo').disabled=true;}
